  'help.type.security': 'אבטחה',
  'help.type.other': 'אחר',
  'help.faq.cantLogin.q': 'לא מצליח לגשת לחשבון שלי',
  'help.faq.cantLogin.a': 'בדוק אם אתה משתמש במייל ובסיסמה הנכונים. אם שכחת את הסיסמה, לחץ על "שכחת את הסיסמה?" במסך הכניסה. אם הבעיה נמשכת, צור כרטיס תמיכה.',
  'help.faq.notReceiving.q': 'לא מקבל מיילים',
