  'help.faq.forgotPassword.q': 'שכחתי את הסיסמה שלי',
  'help.faq.forgotPassword.a': 'במסך הכניסה, לחץ על "שכחת את הסיסמה?" ופעל לפי ההוראות כדי לאפס את הסיסמה שלך דרך המייל לשחזור.',
  'help.faq.accountSecurity.q': 'אני חושב שהחשבון שלי נפרץ',
  'help.faq.accountSecurity.a': 'שנה את הסיסמה שלך מיד. בדוק את תיק המיילים שנשלחו אם שלחת הודעות שלא הכרת. הפעל אימות בשני שלבים בהגדרות > אבטחה. אם צריך, צור כרטיס דחוף.',
  'help.faq.appAccess.q': 'איך אני גישה לאפליקציה במכשיר הנייד?',
  'help.faq.appAccess.a': 'אתה יכול לגשת ל-Chatyy דרך הדפדפן ב-chatyy.com.br, או להוריד את האפליקציה שלנו מחנות האפליקציות של המכשיר שלך.',
  'privacy.title': 'מדיניות פרטיות',
  'privacy.subtitle': 'איך אנחנו מגנים ומטפלים בנתונים שלך',
  'privacy.lastUpdated': 'עדכון אחרון: מרץ 2026',
  'privacy.dataCollection.title': 'איסוף נתונים',
  'privacy.dataCollection.body': 'אנחנו אוספים רק את המידע הנדרש לשירות המייל: השם שלך, כתובת המייל ותוכן ההודעות שנשלחו והתקבלו. אנחנו לא מוכרים ולא משתפים את הנתונים האישיים שלך עם צדדים שלישיים למטרות שיווק.',
  'privacy.dataUsage.title': 'איך אנחנו משתמשים בנתונים שלך',
  'privacy.dataUsage.body': 'הנתונים שלך משמשים אך ורק להפעלת ושיפור שירות המייל, כולל משלוח הודעות, סינון ספאם, תכונות של IA (בהסכמתך) ואבטחת החשבון.',
  'privacy.dataSecurity.title': 'אבטחת נתונים',
  'privacy.dataSecurity.body': 'אנחנו משתמשים בהצפנה סטנדרטית בתעשייה (TLS/SSL) לכל הנתונים במעבר ובמנוחה. מושבים מוגנים עם טוקנים מוצפנים והגנה CSRF. אנחנו בודקים באופן קבוע את הפרקטיקות האבטחתיות שלנו.',
  'privacy.cookies.title': 'עוגיות ואחסון מקומי',
  'privacy.cookies.body': 'אנחנו משתמשים בעוגיות חיוניות ואחסון מקומי כדי לשמור על הסשן שלך, לזכור את ההעדפות שלך (נושא, שפה) ולספק חוויה חלקה. אנחנו לא משתמשים בעוגיות מעקב של צדדים שלישיים.',
  'privacy.thirdParties.title': 'שירותים של צדדים שלישיים',
  'privacy.thirdParties.body': 'אנחנו עשויים להשתמש בשירותים של צדדים שלישיים לפונקציות ספציפיות כמו IA (Anthropic Claude) והודעות פוש. שירותים אלו פועלים לפי המדיניות הפרטית שלהם ומעבדים רק את המינימום הנדרש.',
  'privacy.rights.title': 'הזכויות שלך',
  'privacy.rights.body': 'יש לך את הזכות לגשת, לתקן, לייצא או למחוק את הנתונים האישיים שלך בכל עת. אתה יכול לנהל את הנתונים שלך בהגדרות או ליצור קשר עם התמיכה שלנו.',
  'privacy.contact.title': 'צור קשר',
  'privacy.contact.body': 'לשאלות פרטיות או בקשות נתונים, צור קשר ב-privacy@chatyy.com.br. נענה תוך 30 יום.',
  'terms.title': 'תנאי שירות',
  'terms.subtitle': 'הנחיות שימוש ב-Chatyy',
  'terms.lastUpdated': 'עדכון אחרון: מרץ 2026',
  'terms.acceptance.title': 'קבלת התנאים',
  'terms.acceptance.body': 'בכניסה או בשימוש ב-Chatyy, אתה מסכים לתנאי השירות הללו. אם אינך מסכים עם חלק כלשהו מהתנאים הללו, אל תשתמש בשירות.',
  'terms.services.title': 'תיאור השירותים',
  'terms.services.body': 'ה-Chatyy מספק שירותי תקשורת במייל כולל שליחה, קבלה וניהול מיילים, בנוסף לתכונות IA, אינטגרציה עם לוח שנה ווידיאו קונפרנס.',
  'terms.accounts.title': 'חשבונות משתמש',
  'terms.accounts.body': 'אתה אחראי לשמור על אבטחת האישורים שלך. אל תשתף את הסיסמה שלך ואל תאפשר גישה לא מורשית לחשבון שלך. אתה צריך להיות בן 13 לפחות כדי להשתמש בשירות הזה.',
  'terms.conduct.title': 'שימוש מקובל',
  'terms.conduct.body': 'אתה מסכים לא להשתמש בשירות לשליחת ספאם, תוכנה זדונית, פישינג או כל תוכן לא חוקי. אל תנסה לגשת לחשבונו�� של משתמשים אחרים או להפריע לתשתית השירות.',
  'terms.content.title': 'בעלות על תוכן',
  'terms.content.body': 'אתה שומר על הבעלות על כל תוכן שאתה יוצר ושולח דרך השירות. אנחנו לא טוענים לבעלות על המיילים או הקבצים המצורפים שלך. אנחנו עשויים לעבד את התוכן לפי הצורך כדי לספק את השירות.',
  'terms.limitation.title': 'הגבלת אחריות',
  'terms.limitation.body': 'ה-Chatyy מסופק "כפי שהוא". אנחנו שואפים ל-99.9% זמינות אבל לא מבטיחים שירות רציף. אנחנו לא אחראים לנזקים עקיפים, מקריים או תוצאתיים הנובעים משימוש בשירות.',
  'terms.termination.title': 'סיום חשבון',
  'terms.termination.body': 'אנחנו עשויים להשעות או לסיים חשבונות המפרים את התנאים הללו. אתה יכול למחוק את החשבון שלך בכל עת בהגדרות. לאחר הסיום, הנתונים שלך ימחקו תוך 30 יום.',
  'terms.changes.title': 'שינויים בתנאים',
  'terms.changes.body': 'אנחנו עשויים לעדכן את ��תנאים הללו מעת לעת. נודיע על שינויים משמעותיים במייל או בהודעה באפליקציה. השימוש המתמשך לאחר השינויים מהווה הסכמה לתנאים המעודכנים.',
