  'plans.faqWhatIsPlus': 'מה זה Chatyy One?',
  'plans.faqWhatIsPlusAnswer': 'זהו המנוי הפרימיום של Chatyy שמגן על כל השיחות, התמונות והסרטונים שלך. עם Chatyy One, גם אם תמחוק משהו בטעות, תוכל לשחזר אותו עד 30 יום. בנוסף, אתה מקבל 200GB אחסון, One AI כעוזר אישי, ויכול לשלוח קבצים של עד 100MB.',
  'plans.faqCancelAnswer': 'המנוי שלך יישאר פעיל עד סוף התקופה ששולמה. אחרי זה, תחזור למנוי החינמי. התמונות והסרטונים שלך שעולים על 15GB יישמרו לעוד 30 יום כדי שתוכל להוריד.',
  'plans.faqHowFamily': 'איך עובד המנוי Pro?',
  'plans.faqHowFamilyAnswer': 'אתה יכול להוסיף עד 4 אנשים מהמשפחה שלך. כולם משתפים 500GB אחסון ומקבלים את כל היתרונות של Chatyy One. לכל אחד יש מקום פרטי — אף אחד לא רואה את הקבצים של אחרים.',
  'plans.faqChangePlanAnswer': 'כן! אם תשדרג מ-Plus ל-Pro, תחויב רק בהפרש היחסי. אם תוריד, המנוי הנוכחי יישאר עד סוף התקופה.',
